"Mit Google ist nichts einzutragen: TW-CAD nimmt automatisch den Schlüssel aus der Master-App (gleicher Browser). Abgerechnet wird über dein Google-Konto.": "S Googlem není třeba nic zadávat: TW-CAD automaticky použije klíč z Master aplikace (stejný prohlížeč). Účtuje se přes váš účet Google.",
"z. B.: Bad 2,80 × 2,20 m Innenmaß, Wände 11,5 cm, Tür 88,5 unten links mit 15 cm Abstand, Fenster 101 rechts mittig BRH 1,50, Boden 60×30 Drittelverband, Wand 30×60 bis 2,10 m": "např.: Koupelna 2,80 × 2,20 m vnitřní rozměr, stěny 11,5 cm, dveře 88,5 dole vlevo 15 cm od rohu, okno 101 vpravo uprostřed, parapet 1,50, podlaha 60×30 vazba na třetinu, stěna 30×60 do 2,10 m",
"Zeichnen per Text": "Kreslení textem",
"Plan ändern per Sprache oder Text": "Změna plánu hlasem nebo textem",
"Sag einfach, was geändert werden soll: „Fenster im Bad 1,01 breiter“, „Wand zwischen Küche und Flur 2 cm dicker“, „WC im Gäste-WC an die Nordwand“, „Boden im Flur 60 × 60 Kreuzfuge“ oder frag „wie groß ist das Bad?“. Mit Mikrofon-Knopf auch gesprochen. Kurzbefehl überall: Strg+K.": "Prostě řekněte, co se má změnit: „okno v koupelně o 1,01 širší“, „stěna mezi kuchyní a chodbou o 2 cm silnější“, „WC v toaletě pro hosty k severní stěně“, „podlaha v chodbě 60 × 60 průběžná spára“ nebo se zeptejte „jak velká je koupelna?“. Tlačítkem mikrofonu i hlasem. Zkratka všude: Ctrl+K.",
"Grundriss aus Raumprogramm entwerfen": "Navrhnout půdorys z programu místností",
"Raumprogramm beschreiben (Räume, Größen, Geschosse, Grundstück) – die KI entwirft einen DIN-gerechten Grundriss und TW-CAD baut ihn als neues Projekt mit Wänden, Räumen, Türen, Fenstern, Treppe und Dach auf.": "Popište program místností (místnosti, velikosti, podlaží, pozemek) – AI navrhne půdorys podle norem DIN a TW-CAD z něj vytvoří nový projekt se stěnami, místnostmi, dveřmi, okny, schodištěm a střechou.",
"Visualisierung": "Vizualizace",
"In „3D & Fassade“ (oder „Raum von innen“) rechts unter Export: „KI-Visualisierung“ – die KI schreibt aus dem 3D-Bild fertige Prompts für Bild-KIs (ChatGPT, Firefly, Midjourney) plus Referenzbild und Kundentext.": "V „3D a fasáda“ (nebo „Místnost zevnitř“) vpravo pod Export: „AI vizualizace“ – AI z 3D obrázku napíše hotové prompty pro obrazové AI (ChatGPT, Firefly, Midjourney) a k tomu referenční obrázek a text pro zákazníka.",
"Leistungsverzeichnis auswerten": "Vyhodnotit výkaz výměr",
"LV als PDF, GAEB (X83/D83) oder Text: die KI findet alle Fliesenpositionen mit Hersteller, Serie, Format, Farbe und Fuge und legt sie in der Fliesen-Bibliothek dieses Projekts an. Danach im Fliesenplan „Aus LV/Bibliothek“.": "Výkaz výměr jako PDF, GAEB (X83/D83) nebo text: AI najde všechny položky obkladů a dlažeb s výrobcem, sérií, formátem, barvou a spárou a uloží je do knihovny dlaždic tohoto projektu. Poté v plánu obkladů „Z výkazu/knihovny“.",
