"Name": "Název",
"Ja: Der Plan bleibt unter „Projekte“ (Ordner-Knopf oben) erhalten. Nein: Der Plan wird verworfen – kurz danach kannst du ihn noch einmal zurückholen.": "Ano: plán zůstane v „Projekty“ (tlačítko složky nahoře). Ne: plán se zahodí – krátce poté ho ještě můžete vrátit.",
"Nein – verwerfen": "Ne – zahodit",
