"Aktuelles Projekt als Datei sichern": "Uložit aktuální projekt jako soubor",
"DXF-Zeichnung importieren": "Importovat výkres DXF",
"Wichtig: ": "Důležité: ",
"Deine Projekte liegen nur in diesem Browser auf diesem Gerät. Sichere sie regelmäßig mit „Aktuelles Projekt als Datei sichern“ (.twcad-Datei, z. B. auf USB-Stick oder in deine Cloud) – mit „Datei öffnen“ holst du sie zurück, auch auf einem anderen Gerät.": "Vaše projekty jsou uloženy jen v tomto prohlížeči na tomto zařízení. Pravidelně je zálohujte pomocí „Uložit aktuální projekt jako soubor“ (soubor .twcad, např. na USB disk nebo do cloudu) – přes „Otevřít soubor“ je získáte zpět, i na jiném zařízení.",
"TW-CAD als App": "TW-CAD jako aplikace",
"Läuft als installierte App – funktioniert auch ohne Internet (nur die Hilfe-Videos brauchen Internet).": "Běží jako nainstalovaná aplikace – funguje i bez internetu (jen videa nápovědy potřebují internet).",
"⬇ Als App installieren (Startmenü/Desktop bzw. Home-Bildschirm, offline nutzbar)": "⬇ Nainstalovat jako aplikaci (nabídka Start/plocha nebo domovská obrazovka, i offline)",
"Läuft als installierte App – funktioniert auch ohne Internet (KI, Drive und Hilfe-Videos brauchen Internet).": "Běží jako nainstalovaná aplikace – funguje i bez internetu (AI, Drive a videa nápovědy potřebují internet).",
"⬇ Als App installieren (Startmenü/Desktop, offline nutzbar)": "⬇ Nainstalovat jako aplikaci (nabídka Start/plocha, i offline)",
"iPad/iPhone: in Safari auf „Teilen“ → „Zum Home-Bildschirm“ tippen.": "iPad/iPhone: v Safari klepněte na „Sdílet“ → „Přidat na plochu“.",
"Installieren: im Chrome/Edge-Menü „App installieren“ wählen. Die Programmdateien werden automatisch für den Offline-Betrieb gespeichert.": "Instalace: v nabídce Chrome/Edge zvolte „Nainstalovat aplikaci“. Programové soubory se automaticky uloží pro práci offline.",
"Projekt „{0}“ wirklich löschen?": "Opravdu smazat projekt „{0}“?",
"Gespeicherte Projekte (in diesem Browser)": "Uložené projekty (v tomto prohlížeči)",
"Noch keine.": "Zatím žádné.",
"Projekte werden automatisch in diesem Browser gespeichert. Für eine Sicherung oder zum Weitergeben: „Aktuelles Projekt als Datei sichern“.": "Projekty se automaticky ukládají v tomto prohlížeči. Pro zálohu nebo předání: „Uložit aktuální projekt jako soubor“.",
"Projekte werden automatisch in diesem Browser gespeichert. Mit „Auf Drive speichern“ liegen sie zusätzlich in der Baustelle im Ordner „Zeichnungen“ und sind auf jedem Gerät verfügbar.": "Projekty se automaticky ukládají v tomto prohlížeči. Přes „Uložit na Drive“ jsou navíc ve složce stavby „Výkresy“ a dostupné na každém zařízení.",
