"Einstieg: nur das Nötigste – Raum zeichnen, Fliesen planen, fertig. Oben jederzeit auf „Profi“ umschaltbar.": "Základní: jen to nejnutnější – nakreslit místnost, naplánovat obklady, hotovo. Nahoře lze kdykoli přepnout na „Profi“.",
"Profi: alle Werkzeuge und Ansichten von TW-CAD.": "Profi: všechny nástroje a pohledy TW-CAD.",
"Willkommen! Wie möchtest du arbeiten? Du kannst jederzeit oben zwischen „Einstieg“ und „Profi“ umschalten – deine Zeichnung bleibt dabei vollständig erhalten.": "Vítejte! Jak chcete pracovat? Nahoře můžete kdykoli přepínat mezi „Základní“ a „Profi“ – váš výkres zůstane celý zachován.",
"Einstieg": "Základní",
"Raum zeichnen, Fliesen planen, fertig": "Nakreslit místnost, naplánovat obklady, hotovo",
"Wände, Türen, Fenster, Bad- und Küchenobjekte, Fliesen-Studio mit Verlegeplan und Mengen, 3D-Ansicht und Ausdruck – nur das Nötigste.": "Stěny, dveře, okna, koupelnové a kuchyňské prvky, studio dlaždic s plánem kladení a množstvími, 3D pohled a tisk – jen to nejnutnější.",
"Profi": "Profi",
"Das volle CAD": "Plný CAD",
"Zusätzlich Geschosse, Ebenen, Lageplan & Gelände, Dächer und Gauben, Schnitte und Ansichten, Listen, Plan-Prüfung, DXF/IFC/OBJ/glTF.": "Navíc podlaží, hladiny, situace a terén, střechy a vikýře, řezy a pohledy, seznamy, kontrola plánu, DXF/IFC/OBJ/glTF.",
"Kein Konto, keine Anmeldung: Alles bleibt in deinem Browser gespeichert. Sichere wichtige Projekte als Datei (Ordner-Knopf oben).": "Žádný účet, žádné přihlášení: vše zůstává uloženo ve vašem prohlížeči. Důležité projekty zálohujte jako soubor (tlačítko složky nahoře).",
"Willkommen bei TW-CAD": "Vítejte v TW-CAD",
"TW-CAD": "TW-CAD",
" – Grundriss, Fliesenplanung, 3D und Plandruck": " – půdorys, plánování obkladů, 3D a tisk plánů",
"Kostenlos, ohne Anmeldung und ohne Werbe-Tracking. Deine Projekte bleiben in diesem Browser auf deinem Gerät – es wird nichts hochgeladen.": "Zdarma, bez přihlášení a bez reklamního sledování. Vaše projekty zůstávají v tomto prohlížeči na vašem zařízení – nic se nenahrává.",
"Sichern und Weitergeben: Ordner-Knopf → „Aktuelles Projekt als Datei sichern“ / „Datei öffnen“.": "Záloha a předání: tlačítko složky → „Uložit aktuální projekt jako soubor“ / „Otevřít soubor“.",
"Alle Maße ohne Gewähr – vor der Ausführung am Bau prüfen.": "Všechny rozměry bez záruky – před provedením ověřte na stavbě.",
"Programmstand {0} · ": "Verze programu {0} · ",
