"TW-CAD wird installiert …": "TW-CAD se instaluje …",
"In Safari unten (iPhone) bzw. oben (iPad) auf „Teilen“ (Quadrat mit Pfeil) tippen.": "V Safari klepněte dole (iPhone) nebo nahoře (iPad) na „Sdílet“ (čtverec se šipkou).",
"„Zum Home-Bildschirm“ wählen und „Hinzufügen“ tippen.": "Zvolte „Přidat na plochu“ a klepněte na „Přidat“.",
"TW-CAD startet dann vom Home-Bildschirm wie eine App – auch ohne Internet.": "TW-CAD se pak spouští z plochy jako aplikace – i bez internetu.",
"Chrome / Edge: rechts in der Adressleiste auf das Symbol „App installieren“ (Bildschirm mit Pfeil) klicken – oder im Menü ⋮ „App installieren“ / „TW-CAD installieren“ wählen.": "Chrome / Edge: klikněte vpravo v adresním řádku na ikonu „Nainstalovat aplikaci“ (obrazovka se šipkou) – nebo v nabídce ⋮ zvolte „Nainstalovat aplikaci“ / „Nainstalovat TW-CAD“.",
"Android: im Chrome-Menü ⋮ „App installieren“ bzw. „Zum Startbildschirm hinzufügen“.": "Android: v nabídce Chrome ⋮ „Nainstalovat aplikaci“ nebo „Přidat na plochu“.",
"Firefox und manche andere Browser können Web-Apps nicht installieren – dann TW-CAD einfach als Lesezeichen speichern; es funktioniert genauso.": "Firefox a některé další prohlížeče neumí instalovat webové aplikace – pak si TW-CAD prostě uložte do záložek; funguje stejně.",
