"Treppe passt nicht in „{0}“ ({1} × {2} m) – bitte mit dem Treppen-Werkzeug einsetzen (z. B. gewendelt).": "Schodiště se nevejde do „{0}“ ({1} × {2} m) – vložte ho nástrojem Schodiště (např. točité).",
"z. B.: Einfamilienhaus für 4 Personen, ca. 140 m² Wohnfläche, 2 Geschosse mit Satteldach 38°.\nEG: Diele mit Garderobe, Gäste-WC, Küche offen zu Essen/Wohnen ca. 40 m² nach Süden, Hauswirtschaftsraum, Arbeitszimmer 10 m².\nOG: Eltern 15 m² mit Ankleide, 2 Kinderzimmer je 12 m², Bad 10 m² mit bodengleicher Dusche und Wanne, Abstellraum.\nGrundstück: Haus max. 11 × 9 m, Zufahrt von Westen.": "např.: rodinný dům pro 4 osoby, cca 140 m² obytné plochy, 2 podlaží se sedlovou střechou 38°.\nPřízemí: předsíň s šatnou, WC pro hosty, kuchyně otevřená do jídelny/obývacího pokoje cca 40 m² na jih, technická místnost, pracovna 10 m².\nPatro: rodiče 15 m² se šatnou, 2 dětské pokoje po 12 m², koupelna 10 m² s bezbariérovým sprchovým koutem a vanou, komora.\nPozemek: dům max. 11 × 9 m, příjezd od západu.",
"Die KI entwirft einen Grundriss als Vorschlag (Achsmaße, Raster 12,5 cm) und TW-CAD baut ihn als neues Projekt mit Wänden, Räumen, Türen, Fenstern, Treppe und Dach auf. Danach normal weiterbearbeiten – nichts im aktuellen Projekt wird überschrieben.": "AI navrhne půdorys (osové rozměry, rastr 12,5 cm) a TW-CAD z něj vytvoří nový projekt se stěnami, místnostmi, dveřmi, okny, schodištěm a střechou. Pak běžně pokračujte – nic v aktuálním projektu se nepřepíše.",
