"Flächen sind Netto-Raumflächen aus dem Modell (Innenmaß der Wände, ohne Putzabzug). Wohnfläche nach Wohnflächenverordnung (WoFlV): Raumteile ab 2 m lichter Höhe voll, 1–2 m zur Hälfte, unter 1 m nicht; Balkone/Terrassen in der Regel zu einem Viertel; Keller, Heizungsräume und Garagen zählen nicht zur Wohnfläche. BGF = Brutto-Grundfläche (Außenmaß), KGF = BGF − NRF, BRI ≈ BGF × Geschosshöhe.": "Plochy jsou čisté plochy místností z modelu (vnitřní rozměr stěn, bez odpočtu omítky). Obytná plocha dle německé vyhlášky WoFlV: části místností se světlou výškou od 2 m plně, 1–2 m polovinou, pod 1 m vůbec; balkony/terasy obvykle čtvrtinou; sklepy, kotelny a garáže se do obytné plochy nepočítají. BGF = hrubá podlahová plocha (vnější rozměr), KGF = konstrukční plocha = BGF − NRF (čistá plocha), BRI ≈ BGF × konstrukční výška podlaží (obestavěný prostor).",
