"Nutzung wird aus dem Raumnamen vorgeschlagen (Bad → NUF 7, Flur → VF, Heizung → TF …) und lässt sich je Raum ändern. Dachschrägen werden aus dem Dach berechnet: Wohnfläche ≥ 2 m voll, 1–2 m halb, unter 1 m nicht (§ 4 WoFlV).": "Využití se navrhuje podle názvu místnosti (Koupelna → NUF 7, Chodba → VF, Kotelna → TF …) a lze ho u každé místnosti změnit. Šikmé stropy se počítají ze střechy: obytná plocha ≥ 2 m plně, 1–2 m polovinou, pod 1 m ne (§ 4 WoFlV).",
