"Raumhöhen, Belichtung, Türen, Treppen (DIN 18065), Absturzsicherung, Bewegungsflächen (DIN 18040-2) – Zeile anklicken = im Plan zeigen": "Výšky místností, osvětlení, dveře, schodiště (DIN 18065), zábradlí, manipulační plochy (DIN 18040-2) – klepnutím na řádek = zobrazit v plánu",
