"schließen": "zavřít",
"Keine Einträge in dieser Auswahl.": "V tomto výběru nejsou žádné položky.",
"Noch nichts zu prüfen – zeichne Wände, Räume, Türen und Fenster.": "Zatím není co kontrolovat – nakreslete stěny, místnosti, dveře a okna.",
"Vereinfachte Prüfung aus dem Modell nach {0}, DIN 18065 und DIN 18040-2. Sie ersetzt keine bauaufsichtliche Prüfung; im Zweifel gilt der Normtext bzw. die Landesbauordnung. Räume ohne Aufenthalt (Bad, Flur, Abstellraum …) werden bei Raumhöhe und Belichtung nicht geprüft – die Nutzung stellst du im Raumbuch ein.": "Zjednodušená kontrola z modelu dle {0}, DIN 18065 (schodiště) a DIN 18040-2 (bezbariérové byty). Nenahrazuje úřední kontrolu; v případě pochybností platí text normy, resp. zemský stavební řád. Místnosti bez pobytu (koupelna, chodba, komora …) se z hlediska výšky a osvětlení nekontrolují – využití nastavíte v tabulce místností.",
"Erst KI einrichten (Stern-Knopf oben) – dann erklärt sie die Prüfung.": "Nejdřív nastavte AI (tlačítko s hvězdou nahoře) – pak kontrolu vysvětlí.",
"Alles erfüllt – die Prüfung hat keine Fehler oder Hinweise gefunden. 👍": "Vše splněno – kontrola nenašla chyby ani upozornění. 👍",
